{
  "findings": [
    {
      "check_id": "AVD-AWS-0067",
      "title": "Lambda permission lacks source ARN for *.amazonaws.com principal",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "CRITICAL",
      "explanation": "The Lambda permission allows invocation from 'apigateway.amazonaws.com' without specifying a source ARN, potentially allowing invocation from other accounts or resources."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn = \"${aws_api_gateway_rest_api.log_processing_pipeline.execution_arn}/*/*\"\n}",
  "fix_summary": "Added 'source_arn' attribute to aws_lambda_permission to restrict invocation to a specific API Gateway ARN."
}
